// === Tab: tree_recursion.pde ===
function setup() 
{ 
  createCanvas(600, 600); 
  smooth(); 
  // noLoop() removed for animation 
} 

function draw() 
{ 
  background(255);    
  strokeWeight(10); 
  translate(width/2,height-20); 
  branch(0); 
} 

function branch(depth){ 
  if (depth < 12) { 
    line(0,0,0,-height/10); 
    { 
      translate(0,-height/10); 
      rotate(random(-0.1,0.1));  

      if (random(1.0) < 0.6){ // branching   
        rotate(0.3);
        scale(0.7);
        push(); 
        branch(depth + 1); 
        pop();     
        rotate(-0.6);
        push(); 
        branch(depth + 1);    
        pop();         
      } 
      else { // continue   
        branch(depth);
      } 
    } 
  }
} 


function mouseReleased(){ 
  redraw();  
}
